<?php require dirname(__DIR__, 2) . '/src/common.php'; begin_api(['POST']); try { $body=require_json_body(); $login=$body['login']??null; $password=$body['password']??null; $auth=read_json(path_private('auth.json')); if (!is_string($login)||!is_string($password)||!isset($auth['username'],$auth['passwordHash'])||!hash_equals($auth['username'],$login)||!password_verify($password,$auth['passwordHash'])) api_error(401,'AUTHENTICATION_FAILED'); $token=bin2hex(random_bytes(32)); $expires=gmdate('c', time()+CMS_TOKEN_TTL_SECONDS); $records=token_records(); $records['tokens'][]=['hash'=>token_hash($token),'createdAt'=>gmdate('c'),'expiresAt'=>$expires]; write_tokens($records); json_response(200,['token'=>$token,'expiresAt'=>$expires]); } catch (Throwable) { api_error(500,'LOGIN_FAILED'); }
